import{_ as a,o,c as i,a5 as s}from"./chunks/framework.BwlBv862.js";const h=JSON.parse('{"title":"Autoridade e autenticação de colaboração","description":"","frontmatter":{"title":"Autoridade e autenticação de colaboração","docId":"developer.collaboration","translationKey":"developer.collaboration","locale":"pt","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"fb71673a581e923e3c02ae401a46937b007f9919690ca020d22c27b370b6c61d","translationRevision":"4c37786f426bea10eb9d81bba4fa2d71b04f3936f65a0c0fea62129bad37088a","order":190},"headers":[],"relativePath":"pt/developer/collaboration.md","filePath":"pt/developer/collaboration.md","lastUpdated":1794611623000}'),t={name:"pt/developer/collaboration.md"};function r(d,e,n,c,l,p){return o(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="collaboration-authority-and-authentication" tabindex="-1">Autoridade e autenticação de colaboração <a class="header-anchor" href="#collaboration-authority-and-authentication" aria-label="Permalink to &quot;Autoridade e autenticação de colaboração {#collaboration-authority-and-authentication}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Permita que um dispositivo aprovado inspecione ou execute uma operação de escopo restrito em um host existente. Use um perfil de proprietário de teste, uma compilação com suporte remoto e um transporte configurado. Login de conta, participação em equipe do Cloud, propriedade local e sessão delegada direta são autoridades distintas.</p><h2 id="establish-the-trust-chain" tabindex="-1">Estabeleça a cadeia de confiança <a class="header-anchor" href="#establish-the-trust-chain" aria-label="Permalink to &quot;Estabeleça a cadeia de confiança {#establish-the-trust-chain}&quot;">​</a></h2><p>A administração <code>collaboration.*</code> do proprietário local é responsável por configuração, convites, solicitações pendentes, identidades, concessões, sessões e auditoria. Descubra esquemas antes de configurar um receptor ou criar credenciais:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> collaboration.configure</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> collaboration.invites.create</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> collaboration.status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span></span></code></pre></div><p>Um convite inicia o pareamento; ele não concede, por si só, autoridade de negócio. A aprovação do proprietário cria a sessão/concessões adequadas. HTTPS direto exige certificados validados ou confiança nativa fixada explicitamente. Os limites de token de portador nativo e cookie de navegador diferem. O <code>collaboration.hello</code> inicial vincula protocolo, instância do host, identidade, sessão, revisão da concessão, capacidades e limites negociados.</p><h2 id="authorize-each-operation" tabindex="-1">Autorize cada operação <a class="header-anchor" href="#authorize-each-operation" aria-label="Permalink to &quot;Autorize cada operação {#authorize-each-operation}&quot;">​</a></h2><p>Um método remoto compatível deve passar por sua lista de permissões, capacidade, restrição de recursos e verificações da sessão atual. Desativar/excluir fluxos usa metadados duráveis de comparação e troca. Ajustes de pontos são aditivos e têm seus próprios limites de concessão. Leituras remotas de automações são resumos fechados; rascunhos desativados sob autoria do criador não podem adquirir autoridade executável do proprietário apenas por serem salvos.</p><p>Revisão/adoção pelo proprietário e aprovação verificada vinculam definições atuais, dependências e procedência. Um manifesto de prévia informa dados de inspeção, não um token de execução. Revalide concessões e vínculos de recursos nos limites de execução, em vez de tratar a identidade do transporte como permissão permanente.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado e status {#expected-result-and-status}&quot;">​</a></h2><p>A colaboração nativa direta implementa leituras com escopo, mutações duráveis selecionadas e recuperação limitada. Equipes/relay do Cloud também têm seus próprios adaptadores; o caminho documentado de leitura por relay do Cloud não deve ser apresentado como moderação completa ou execução de rascunhos. Efeitos delegados restantes, gravações de domínio e aceitação entre vários PCs continuam experimentais. Consulte <a href="./remote-client.html">clientes remotos</a> e <a href="./cloud.html">Cloud</a> para o caminho selecionado.</p><h2 id="recover-and-verify" tabindex="-1">Recupere e verifique <a class="header-anchor" href="#recover-and-verify" aria-label="Permalink to &quot;Recupere e verifique {#recover-and-verify}&quot;">​</a></h2><p>Em revogação ou mudança de identidade, pare assinaturas e descarte projeções privadas. Use <code>collaboration.subscribe</code>, <code>snapshot</code> e <code>resume</code> conforme os domínios negociados e a validade do cursor. Resolva o ID original do comando após uma confirmação incerta. Não repita uma exclusão com um ID novo nem restaure autoridade de um recibo antigo. O <a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-collaboration/src" target="_blank" rel="noreferrer">código de autorização</a> e a política do registro definem o limite; passar pelo TLS sozinho não é um teste de autorização.</p><h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalhes de operação {#operational-details}&quot;">​</a></h2><p>Sequência Teams: registre dispositivo, emita/aceite convite ou solicitação, aprove e faça o host confirmar a revisão atual da permissão nativa. <code>pendingHost</code> indica essa etapa pendente. Nova revisão invalida a confirmação anterior; atualize se expectedRevision vencer. Aceitação nativa exige captura recente, host/dispositivo ativos, permissão ativa e confirmedRevision igual a revision. A UI oferece painéis host/entrada e aprovações disponíveis; confirmação nativa é contrato API, não botão garantido em toda build.</p><p>Conversão legada fechada: observer lê live/workflows/pontos/competição/automação/resultados; moderator acrescenta ajuste de pontos, toggles workflow/automação e gestão de competição; automationEditor acrescenta edição às leituras. Nenhum preset implica scripts arbitrários, efeitos externos ou delegação reutilizável. <code>nativeGrant</code> explícito exige <code>custom</code>; restrinja recursos, efeitos e delta ali. Cliente nativo só <code>desktop</code> ou <code>agent</code>. Política incompatível falha sem ampliar direitos. Diagnostique pairing, confirmação, revisão e transporte separadamente.</p>`,17)])])}const m=a(t,[["render",r]]);export{h as __pageData,m as default};
